{
  "ledger": {
    "p77:e595": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "단편적 대화 마커('Worked for 1m >'). 연구 내용이라기보다 상태 표시 조각. 승인된 사실에 표현되지 않음."
    },
    "p77:e596": {
      "state": "represented",
      "fact_ids": ["P0077F0001"],
      "note": "'초소형 데이터(1 KB)의 역설' 해석 내용 전체가 P0077F0001에 보존됨."
    },
    "p77:e597": {
      "state": "unresolved",
      "fact_ids": ["P0077F0002"],
      "note": "첫 문장('Pinned Memory가 무조건 빠르다 / 데이터가 충분히 클 때')은 P0077F0002에 보존됨. 그러나 두 번째 문장 '왜 1,028 Byte(1 KB)에서 No-Pin(일반 메모리)이 더 빠른지 그 하드웨어적 비밀을 명쾌하게 풀어드리겠습니다'는 어떤 승인된 사실에도 표현되지 않음."
    },
    "p77:e598": {
      "state": "represented",
      "fact_ids": ["P0077F0003"],
      "note": "목록 제목('1. 비유: 옆집 가는데 KTX 타는 격'). 제목 자체는 별도 사실로 보존되지 않았으나, 비유 내용은 P0077F0003의 observations에 포함됨."
    },
    "p77:e599": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "목록 헤더('No-Pin (일반 메모리 → CPU가 직접 복사)'). 헤더 자체는 보존되지 않음. 이 헤더가 소개하는 본문(e600)의 핵심 수치(20~30ns)도 누락됨."
    },
    "p77:e600": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "CPU L1 캐시 → 드라이버 내부 버퍼 복사 시간 '20~30 나노초(0.00003 ms)'라는 구체적 수치가 어떤 승인된 사실에도 측정값/관찰값으로 보존되지 않음. P0077F0003은 DMA 셋업 오버헤드(1~2μs)만 다루고 있음."
    },
    "p77:e601": {
      "state": "represented",
      "fact_ids": ["P0077F0003"],
      "note": "목록 헤더('Pinned Memory (GPU DMA 엔진 호출)'). 헤더 자체는 보존되지 않았으나 소개되는 본문(e602)은 P0077F0003에 보존됨."
    },
    "p77:e602": {
      "state": "represented",
      "fact_ids": ["P0077F0003"],
      "note": "DMA 엔진 가동 방식, 1~2μs 셋업 오버헤드, KTX 비유 전체가 P0077F0003에 보존됨. 측정값(1μs, 2μs)도 포함됨."
    },
    "p77:e603": {
      "state": "represented",
      "fact_ids": ["P0077F0004"],
      "note": "92만 번 루프, DMA 셋업 누적, infer 단계 13초 차이(132초 vs 119초) 전체가 P0077F0004에 보존됨."
    },
    "p77:enh:e0": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "p77:e595와 duplicate. 동일 단편 조각."
    },
    "p77:enh:e1": {
      "state": "represented",
      "fact_ids": ["P0077F0001"],
      "note": "p77:e596과 duplicate. 동일 내용."
    },
    "p77:enh:e2": {
      "state": "represented",
      "fact_ids": ["P0077F0002"],
      "note": "p77:e597의 첫 문장과 duplicate. P0077F0002에 보존됨."
    },
    "p77:enh:e3": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "p77:e597의 두 번째 문장과 duplicate. '왜 1,028 Byte에서 No-Pin이 더 빠른지 풀어드리겠습니다' 부분이 보존되지 않음."
    },
    "p77:enh:e4": {
      "state": "represented",
      "fact_ids": ["P0077F0003"],
      "note": "p77:e598과 duplicate. 제목 자체는 별도 사실 아님."
    },
    "p77:enh:e5": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "p77:e599와 duplicate. 목록 헤더."
    },
    "p77:enh:e6": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "p77:e600과 duplicate. 20~30 나노초 수치 누락 동일."
    },
    "p77:enh:e7": {
      "state": "represented",
      "fact_ids": ["P0077F0003"],
      "note": "p77:e601과 duplicate. 헤더."
    },
    "p77:enh:e8": {
      "state": "represented",
      "fact_ids": ["P0077F0003"],
      "note": "p77:e602와 duplicate. 내용 및 측정값 보존됨."
    },
    "p77:enh:e9": {
      "state": "represented",
      "fact_ids": ["P0077F0004"],
      "note": "p77:e603과 duplicate. enh 버전에 오타('$\\\\mu\\\\text{tu}\\\\text{text{s}$') 있으나 의미 동일. P0077F0004에 보존됨."
    }
  }
}
